INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(34311, 'Mark 6:6', 'Mark', 6, 6, 'او عیسی د هغوی په بې‌ایمانۍ حیران شو. عیسی دولس رسولان لېږي (متي ۱۰‏:‌۵‌‏-‌۱۵ او لوقا ۹‏:‌۱‌‏-‌۶) عیسی کلي په کلي ګرځېده او خلکو ته یې تعلیم ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_6.mp3', '', 1761754199, 1761754199),
(34312, 'Mark 6:7', 'Mark', 6, 7, 'هغه خپل دولس رسولان راوغوښتل او هغوی یې دوه دوه تنه ولېږل او هغوی ته یې د پېریانو د ویستلو اختیار ورکړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_7.mp3', '', 1761754199, 1761754199),
(34313, 'Mark 6:8', 'Mark', 6, 8, 'او حکم یې ورته وکړ: «د سفر دپاره له یوې امسا پرته بل هېڅ شی د ځان سره وانخلئ، نه ډوډۍ، نه خورجین او نه پیسې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_8.mp3', '', 1761754199, 1761754199),
(34314, 'Mark 6:9', 'Mark', 6, 9, 'تاسو کولای شئ چې څپلۍ په پښو کړئ، خو اضافه کالي درسره مه اخلئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_9.mp3', '', 1761754199, 1761754199),
(34315, 'Mark 6:10', 'Mark', 6, 10, 'او دا یې هم ورته وویل: «کله چې تاسو کوم کور ته ننوځئ نو تر هغې پورې چې له هغه ښار څخه ځئ، هلته پاتې شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_10.mp3', '', 1761754199, 1761754199),
(34316, 'Mark 6:11', 'Mark', 6, 11, 'او که چېرې په کوم ځای کې خلک تاسو قبول نه کړي او یا ستاسو خبرو ته غوږ ونه نیسي، نو له هغه ځای څخه لاړ شئ او د خپلو پښو خاورې وڅنډئ ترڅو د هغوی په خلاف شاهدي شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_11.mp3', '', 1761754199, 1761754199),
(34317, 'Mark 6:12', 'Mark', 6, 12, 'نو شاګردان لاړل او خلکو ته یې وعظ کاوه چې باید توبه وباسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_12.mp3', '', 1761754199, 1761754199),
(34318, 'Mark 6:13', 'Mark', 6, 13, 'هغوی ډېر پېریان وویستل او د ډېرو ناروغانو سرونه یې د زیتون په تېلو باندې غوړ کړل او هغوی یې روغ کړل. د تعمید غسل ورکوونکي یحیی مړینه (متي ۱۴‏:‌۱‌‏-‌۱۲ او لوقا ۹‏:‌۷‌‏-‌۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_13.mp3', '', 1761754199, 1761754199),
(34319, 'Mark 6:14', 'Mark', 6, 14, 'د دې کارونو څخه هیرودیس پاچا خبر شو، ځکه چې د عیسی نوم په هرځای کې مشهور شوی ؤ، ځینو خلکو ویل: «تعمید ورکوونکی یحیی بیا راژوندی شوی دی، نو له دې امله هغه دا قدرت لري چې معجزې وښایي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_14.mp3', '', 1761754199, 1761754199),
(34320, 'Mark 6:15', 'Mark', 6, 15, 'نورو به ویل: «هغه الیاس نبي دی.» او ځینو به ویل: «دا د پخوانیو پیغمبرانو په شان یو پیغمبر دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_15.mp3', '', 1761754199, 1761754199),
(34321, 'Mark 6:16', 'Mark', 6, 16, 'خو کله چې هیرودیس د عیسی د کارونو څخه خبر شو، نو ویې ویل: «دا هماغه یحیی دی چې ما یې سر پرې کړی ؤ او اوس بېرته راژوندی شوی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_16.mp3', '', 1761754199, 1761754199),
(34322, 'Mark 6:17', 'Mark', 6, 17, 'ځکه چې هیرودیس په خپله امر کړی ؤ چې یحیی دې ونیول شي، هغه دې وتړل شي او په زندان کې دې واچول شي. هیرودیس دا کار د هیرودیا په خاطر کړی ؤ. هیرودیا د هیرودیس د ورور فیلیپوس ښځه وه، خو هیرودیس ورسره واده کړی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_17.mp3', '', 1761754199, 1761754199),
(34323, 'Mark 6:18', 'Mark', 6, 18, 'یحیی به هیرودیس ته ویل: «تاته روا نه ده چې د خپل ورور د ښځې سره واده وکړې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_18.mp3', '', 1761754199, 1761754199),
(34324, 'Mark 6:19', 'Mark', 6, 19, 'نو دهیرودیا په زړه کې د یحیی سره کینه پیدا شوې وه او غوښتل یې چې هغه ووژني، خو هغې دا کار نه شو کولای،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_19.mp3', '', 1761754199, 1761754199),
(34325, 'Mark 6:20', 'Mark', 6, 20, 'ځکه چې هیرودیس د یحیی څخه وېرېده. هغه پوهېده چې یحیی نېک او پاک سړی دی، نو د هغه ساتنه یې کوله. چې کله به هغه د یحیی خبرې اورېدلې، نو ډېر نا‌ارامه کېده، خو بیاهم په شوق سره یې د هغه خبرو ته غوږ نیوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_20.mp3', '', 1761754199, 1761754199),
(34326, 'Mark 6:21', 'Mark', 6, 21, 'په پای کې هیرودیا یوه مناسبه موقعه پیدا کړه. هیرودیس د خپلې زېږېدنې د کلیزې د لمانځلو په خاطر یوه مېلمستیا جوړه کړه او په هغې کې یې خپل لوړ‌رتبه مامورین، عسکري قوماندانان او د جلیل مخور خلک رابللي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_21.mp3', '', 1761754199, 1761754199),
(34327, 'Mark 6:22', 'Mark', 6, 22, 'په دې وخت کې د هیرودیا لور دننه راغله او ګډا یې وکړه او هیرودیس او د هغه مېلمانه یې دومره خوشحاله کړل چې پاچا هغې انجلۍ ته وویل: «هرڅه چې غواړې ویې غواړه، زه به یې درکړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_22.mp3', '', 1761754199, 1761754199),
(34328, 'Mark 6:23', 'Mark', 6, 23, 'او د هغې سره یې قسم وخوړ: «هرڅه چې زما څخه وغواړې زه به یې درکړم، حتی خپله نیمه پاچاهي هم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_23.mp3', '', 1761754199, 1761754199),
(34329, 'Mark 6:24', 'Mark', 6, 24, 'هغه انجلۍ دباندې ووتله او د خپلې مور څخه یې پوښتنه وکړه: «زه ترې څه وغواړم؟» مور یې ځواب ورکړ: «د تعمید غسل ورکوونکي یحیی سر.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_24.mp3', '', 1761754199, 1761754199),
(34330, 'Mark 6:25', 'Mark', 6, 25, 'انجلۍ په بیړه بېرته پاچا ته ورغله او د هغه څخه یې غوښتنه وکړه: «زه ستا څخه غواړم چې همدا‌اوس راته د تعمید غسل ورکوونکي یحیی سر په پتنوس کې راکړې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_25.mp3', '', 1761754199, 1761754199),
(34331, 'Mark 6:26', 'Mark', 6, 26, 'پاچا ډېر زیات غمجن شو، خو د خپل قسم په خاطر چې د خپلو مېلمنو په مخکې یې خوړلی ؤ ونه غوښتل چې د هغې سره خپل قسم مات کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_26.mp3', '', 1761754199, 1761754199),
(34332, 'Mark 6:27', 'Mark', 6, 27, 'نو پاچا سمدلاسه جلاد ولېږه او حکم یې ورته وکړ چې د یحیی سر راوړي. جلاد لاړ او په زندان کې یې د یحیی سر پرې کړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_27.mp3', '', 1761754199, 1761754199),
(34333, 'Mark 6:28', 'Mark', 6, 28, 'او هغه یې په یو پتنوس کې راوړ او هغې انجلۍ ته یې ورکړ او هغې خپلې مور ته ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_28.mp3', '', 1761754199, 1761754199),
(34334, 'Mark 6:29', 'Mark', 6, 29, 'کله چې د یحیی شاګردان له دې نه خبر شول، نو هغوی راغلل او د هغه مړی یې یووړ او په قبر کې یې ښخ کړ. عیسی پنځه زره سړیو ته خواړه ورکوي (متي ۱۴‏:‌۱۳‌‏-‌۲۱ او لوقا ۹‏:‌۱۰‌‏-‌۱۷ او یوحنا ۶‏:‌۱‌‏-‌۱۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_29.mp3', '', 1761754199, 1761754199),
(34335, 'Mark 6:30', 'Mark', 6, 30, 'رسولان بېرته عیسی ته راغلل او هرڅه چې هغوی کړي وو او کوم تعلیم چې یې ورکړی ؤ هغه یې ترې خبر کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_30.mp3', '', 1761754199, 1761754199),
(34336, 'Mark 6:31', 'Mark', 6, 31, 'دومره ډېر خلک تلل او راتلل چې عیسی او شاګردانو یې دومره وخت هم نه درلود چې ډوډۍ وخوري، نو عیسی هغوی ته وویل: «راځئ چې یو داسې ځای ته لاړ شو چې هلته یوازې اوسو او لږ ارام وکړو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_31.mp3', '', 1761754199, 1761754199),
(34337, 'Mark 6:32', 'Mark', 6, 32, 'بیا هغوی خپله په کشتۍ کې یو ګوښه ځای ته لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_32.mp3', '', 1761754199, 1761754199),
(34338, 'Mark 6:33', 'Mark', 6, 33, 'خو ډېرو خلکو هغوی ولیدل چې روان وو او هغوی یې وپېژندل او خلکو د ټولو ښارونو نه په پښو باندې هغه ځای ته ورمنډې کړې او د هغوی څخه مخکې هلته ورسېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_33.mp3', '', 1761754199, 1761754199),
(34339, 'Mark 6:34', 'Mark', 6, 34, 'کله چې عیسی د کشتۍ څخه ښکته شو او د خلکو یوه لویه ګڼه‌ګوڼه یې ولیدله نو زړه یې ورباندې وسوځېد، ځکه چې هغوی د بې‌شپونه پسونو په شان وو. نو هغوی ته یې د ډېرو شیانو په هکله تعلیم ورکول پیل کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_34.mp3', '', 1761754199, 1761754199),
(34340, 'Mark 6:35', 'Mark', 6, 35, 'کله چې ماښام شو، نو شاګردان یې ورته راغلل او ورته ویې ویل: «دا ځای د دښتې په شان دی او ناوخته شوې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_35.mp3', '', 1761754199, 1761754199),
(34341, 'Mark 6:36', 'Mark', 6, 36, 'خلک رخصت کړه چې شاوخوا کلیو او بانډو ته لاړ شي او ځانونو ته د خوړلو دپاره کوم څه واخلي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_36.mp3', '', 1761754199, 1761754199),
(34342, 'Mark 6:37', 'Mark', 6, 37, 'خو عیسی وویل: «تاسو خپله هغوی ته څه ورکړئ چې ویې خوري.» هغوی ورته وویل: «ایا مونږ لاړ شو او هغوی ته د سپینو زرو په دوه سوه سکو ډوډۍ واخلو او وریې کړو چې ویې خوري؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_37.mp3', '', 1761754199, 1761754199),
(34343, 'Mark 6:38', 'Mark', 6, 38, 'عیسی د هغوی څخه پوښتنه وکړه: «ستاسو سره څومره ډوډۍ شته؟ لاړ شئ او ویې ګورئ.» کله چې هغوی ولیدل، نو هغه ته یې وویل: «زمونږ سره پنځه ډوډۍ دي او دوه ماهیان.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_38.mp3', '', 1761754199, 1761754199),
(34344, 'Mark 6:39', 'Mark', 6, 39, 'بیا عیسی خپلو شاګردانو ته امر وکړ چې خلک ډله ډله په شنو واښو باندې کښېنوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_39.mp3', '', 1761754199, 1761754199),
(34345, 'Mark 6:40', 'Mark', 6, 40, 'نو خلک په قطارونو کې ډله ډله کښېناستل او په هره ډله کې سل سل او پنځوس پنځوس تنه وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_40.mp3', '', 1761754199, 1761754199),
(34346, 'Mark 6:41', 'Mark', 6, 41, 'بیا عیسی هغه پنځه ډوډۍ او دوه ماهیان راواخیستل، اسمان ته یې وکتل، د خدای شکر یې وویست او ډوډۍ یې ماتې کړې. هغه یې شاګردانو ته ورکړې چې په خلکو یې ووېشي. هغه همدارنګه هغه دوه ماهیان هم په هغوی ووېشل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_41.mp3', '', 1761754199, 1761754199),
(34347, 'Mark 6:42', 'Mark', 6, 42, 'هغوی ټولو وخوړل او ماړه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_42.mp3', '', 1761754199, 1761754199),
(34348, 'Mark 6:43', 'Mark', 6, 43, 'شاګردانو د پاتې شویو ډوډیو او ماهیانو څخه دولس ټوکرۍ ډکې کړې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_43.mp3', '', 1761754199, 1761754199),
(34349, 'Mark 6:44', 'Mark', 6, 44, 'کومو خلکو چې ډوډۍ خوړلې وه شمېر یې پنځه زره سړیو ته رسېده. عیسی د اوبو دپاسه ګرځي (متي ۱۴‏:‌۲۲‌‏-‌۳۳ او یوحنا ۶‏:‌۱۵‌‏-‌۲۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_44.mp3', '', 1761754199, 1761754199),
(34350, 'Mark 6:45', 'Mark', 6, 45, 'بیا عیسی خپل شاګردان مجبور کړل چې کشتۍ ته وخېژي او د هغه څخه مخکې د بحیرې بلې غاړې بیت‌صیدا ته لاړ شي. عیسی هلته پاتې شو ترڅو خلک رخصت کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_45.mp3', '', 1761754199, 1761754199),
(34351, 'Mark 6:46', 'Mark', 6, 46, 'کله چې عیسی د هغوی سره خدای پاماني وکړه، نو په خپله غره ته وخوت چې دعا وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_46.mp3', '', 1761754199, 1761754199),
(34352, 'Mark 6:47', 'Mark', 6, 47, 'کله چې ماښام شو، نو د شاګردانو کشتۍ د بحیرې په منځ کې وه او عیسی په وچه کې یوازې پاتې ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_47.mp3', '', 1761754199, 1761754199),
(34353, 'Mark 6:48', 'Mark', 6, 48, 'عیسی ولیدل چې شاګردان یې په ډېر زحمت سره کشتۍ بیایي، ځکه چې باد ورته مخامخ ؤ. سهار وختي چې لا تیاره وه عیسی د اوبو دپاسه ګرځېده او شاګردانو ته ورغی. هغه غوښتل چې د هغوی له څنګه تېر شي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_48.mp3', '', 1761754199, 1761754199),
(34354, 'Mark 6:49', 'Mark', 6, 49, 'خو کله چې شاګردانو هغه ولیده چې د اوبو دپاسه روان دی، نو فکر یې وکړ چې دا د مړو ارواح ده نو چیغې یې کړې،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_49.mp3', '', 1761754199, 1761754199),
(34355, 'Mark 6:50', 'Mark', 6, 50, 'ځکه چې هغوی ټولو هغه ولیده او سخت ووېرېدل. خو عیسی سمدلاسه د هغوی سره خبرې وکړې او ویې ویل: «زړور اوسئ، زه یم، مه وېرېږئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_50.mp3', '', 1761754199, 1761754199),
