(34360, 'Mark 6:55', 'Mark', 6, 55, 'او هغوی په منډه منډه شاوخوا ټولو سیمو ته لاړل او چېرته چې به خلکو وویل چې عیسی په هغه ځای کې دی، نو هغوی به خپل ناروغان ورته په کټونو کې راوړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_55.mp3', '', 1761754199, 1761754199),
(34361, 'Mark 6:56', 'Mark', 6, 56, 'عیسی به چې هر کلي، ښار او بانډې ته تللو، نو خلکو به ورته بازارونو ته خپل ناروغان وړل او زارۍ به یې ورته کولې چې ناروغانو ته دومره اجازه ورکړي چې لږ تر لږه د هغه لمنې ته لاس وروړي او هرچا چې به لاس وروړ، نو هغه به روغېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark6_verse_56.mp3', '', 1761754199, 1761754199),
(34362, 'Luke 23:1', 'Luke', 23, 1, 'بیا د شورا ټول غړي پاڅېدل او عیسی یې پیلاتوس ته بوته', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_1.mp3', '', 1761754199, 1761754199),
