(34399, 'Luke 23:38', 'Luke', 23, 38, 'د هغه د سر دپاسه یوه تخته لګول شوې وه چې ورباندې لیکل شوي وو: «دا د یهودیانو پاچا دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_38.mp3', '', 1761754199, 1761754199),
(34400, 'Luke 23:39', 'Luke', 23, 39, 'یو له هغو مجرمانو څخه چې هلته ځړول شوی ؤ عیسی ته پېغور ورکړ او ویې ویل: «ایا ته مسیح نه یې؟ نو بیا خپل ځان او مونږ وژغوره.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_39.mp3', '', 1761754199, 1761754199),
(34401, 'Luke 23:40', 'Luke', 23, 40, 'خو هغه بل مجرم هغه ورټلو او ورته ویې ویل: «ایا ته له خدایه نه وېرېږې؟ ځکه چې په تا باندې هم د هغه په شان د مرګ حکم شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_40.mp3', '', 1761754199, 1761754199),
(34402, 'Luke 23:41', 'Luke', 23, 41, 'زمونږ سره انصاف شوی دی، ځکه چې مونږ ته د خپلو عملونو سزا راکول کیږي. خو دې سړي کوم غلط کار نه دی کړی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_41.mp3', '', 1761754199, 1761754199),
(34403, 'Luke 23:42', 'Luke', 23, 42, 'بیا هغه وویل: «ای عیسی! کله چې خپلې پاچاهۍ ته ورسېدې، نو ما هم در په یاد کړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_42.mp3', '', 1761754199, 1761754199),
(34404, 'Luke 23:43', 'Luke', 23, 43, 'عیسی هغه ته وویل: «په یقین سره زه تاته وایم چې ته به نن زما سره په جنت فردوس کې اوسې.» د عیسی مړینه (متي ۲۷‏:‌۴۵‌‏-‌۵۶ او مرقوس ۱۵‏:‌۳۳‌‏-‌۴۱ او یوحنا ۱۹‏:‌۲۸‌‏-‌۳۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_43.mp3', '', 1761754199, 1761754199),
(34405, 'Luke 23:44', 'Luke', 23, 44, '‏-۴۵ د غرمې شاوخوا دولس بجې وې چې لمر ورک شو او د ماسپښین تر درې بجو پورې په ټوله سیمه کې تیاره خپره شوه او د خدای د کور پرده په منځ کې دوه ټوټې شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_44.mp3', '', 1761754199, 1761754199),
(34406, 'Luke 23:46', 'Luke', 23, 46, 'عیسی په لوړ اواز چیغه ووهله او ویې ویل: «ای پلاره! زه خپل روح تاته سپارم.» دا یې وویل او ساه یې ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_46.mp3', '', 1761754199, 1761754199),
(34407, 'Luke 23:47', 'Luke', 23, 47, 'کله چې رومي منصبدار دا هرڅه ولیدل، نو د خدای ثنا یې وویله او ویې ویل: «بې له شکه چې دا سړی بې‌ګناه ؤ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_47.mp3', '', 1761754199, 1761754199),
(34408, 'Luke 23:48', 'Luke', 23, 48, 'هغه خلک چې دې نندارې ته راټول شوي وو، کله یې چې دا پېښه ولیدله، نو له غمه یې خپل ځانونه وهل او بېرته خپلو کورونو ته لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_48.mp3', '', 1761754199, 1761754199),
(34409, 'Luke 23:49', 'Luke', 23, 49, 'د عیسی ټول اشنایان او هغه ښځې چې د جلیل څخه هغه پسې راغلې وې په لېرې فاصله کې ولاړې وې او دا هرڅه یې لیدل. د عیسی ښخېدل (متي ۲۷‏:‌۵۷‌‏-‌۶۱ او مرقوس ۱۵‏:‌۴۲‌‏-‌۴۷ او یوحنا ۱۹‏:‌۳۸‌‏-‌۴۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_49.mp3', '', 1761754199, 1761754199),
(34410, 'Luke 23:50', 'Luke', 23, 50, 'هلته د یوسف په نوم یو سړی ؤ چې په یهودیه کې د رامه د ښار څخه ؤ او د یهودیانو د شورا غړی ؤ. هغه یو نېک او عادل سړی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_50.mp3', '', 1761754199, 1761754199);